class BoundedList {
    private String[] items;
    private int count = 0;
    BoundedList(int capacity) { items = new String[capacity]; }
    public boolean add(String item) {
        if (count >= items.length) return false;
        items[count++] = item;
        return true;
    }
    public void remove(int index) {
        for (int i = index; i < count - 1; i++) items[i] = items[i + 1];
        count--;
    }
    public String get(int index) { return items[index]; }
}

public static void main(String[] args) {
    BoundedList list = new BoundedList(5);
    list.add("A"); list.add("B"); list.add("C");
    list.remove(1);
    list.add("D");
    for (int i = 0; i < 3; i++) System.out.println(list.get(i));
}

