class PriceHistory {
    private double[] prices = new double[10];
    private int count = 0;
    public void addPrice(double price) {
        if (count < prices.length) prices[count++] = price;
    }
    public double average() {
        double sum = 0;
        for (int i = 0; i < count; i++) sum += prices[i];
        return sum / count;
    }
    public double max() {
        double m = prices[0];
        for (int i = 0; i < count; i++) if (prices[i] > m) m = prices[i];
        return m;
    }
    public double min() {
        double m = prices[0];
        for (int i = 0; i < count; i++) if (prices[i] < m) m = prices[i];
        return m;
    }
    public double[] getHistory() { return java.util.Arrays.copyOf(prices, count); }
    public void printTrend() {
        for (int i = 1; i < count; i++) {
            String trend = prices[i] > prices[i - 1] ? "up" : "down";
            System.out.println(prices[i - 1] + " -> " + prices[i] + " (" + trend + ")");
        }
    }
}

public static void main(String[] args) {
    PriceHistory history = new PriceHistory();
    double[] ceny = {10, 12, 11, 15, 14, 16, 18};
    for (double c : ceny) history.addPrice(c);
    System.out.println("Średnia: " + history.average());
    System.out.println("Max: " + history.max() + ", Min: " + history.min());
    history.printTrend();
}
